export const monsterCatalog = new Map([
    ...definitions.map((definition) => [
        definition.id,
        {
            ...definition,
            grade: 'normal',
            mapId: null,
            assetId: `ai/monster-${definition.id}`,
            assetPath: `public/assets/maplestory/monster-expansion/${definition.id}/`,
        },
    ]),
    ...mapBossDefinitions.map((definition) => [
        definition.id,
        { ...definition, assetId: `ai/monster-${definition.id}` },
    ]),
]);
export const normalMonsterIds = definitions.map((definition) => definition.id);
export const monsterIds = [...monsterCatalog.keys()];
export const monsterGradeNames = {
    normal: '일반',
    miniboss: '중간보스',
    boss: '보스',
};
export function monsterBattleName(id) {
    const monster = monsterDefinition(id);
    return monster.grade === 'normal'
        ? monster.name
        : `${monsterGradeNames[monster.grade]} · ${monster.name}`;
}
export const monsterRoleNames = {
    striker: '타격형',
    rusher: '기습형',
    armored: '갑옷형',
    charger: '예고 강타형',
    ranged: '원거리형',
    support: '지원형',
};
export const monsterThemeNames = {
    forest: '숲',
    wetland: '습지',
    ridge: '산등성이',
    ruins: '유적',
    snow: '설원',
};
export function isMonsterId(value) {
    return typeof value === 'string' && monsterIds.some((id) => id === value);
}
export function monsterDefinition(id) {
    const definition = monsterCatalog.get(id);
    if (!definition)
        throw new Error(`등록되지 않은 몬스터입니다: ${id}`);
    return definition;
}
